#!/bin/sh
# GENERATED by bake.py -- the feed half of Preware's own postinst
# (org.webosinternals.preware/control/postinst), plus CE ipkg status
# stanzas for the packages this image bakes. Run once per flash by
# /etc/event.d/ce-cryptofs-seed, AFTER first use (the cryptofs store is
# re-initialized during first-use, so anything written before is lost).
# Do not edit: change Preware's postinst, or bake.py.

APPS=/media/cryptofs/apps
[ -d "$APPS" ] || { echo "no $APPS -- cryptofs not ready"; exit 1; }

# Extract the OS version for the version-specific patch and kernel feeds.
# Do not assume where the version sits in the string: it trails the vendor on
# stock builds ("HP webOS 3.0.5") but trails the edition on Community Edition
# builds ("webOS CE 3.1.0").  So take the last dotted-numeric token on the
# line, which also survives a digit in the device name ("Palm Pre2 webOS
# 2.2.4") and a suffixed or parenthesised build tag.
VERSION=`grep PRODUCT_VERSION_STRING /etc/palm-build-info 2>/dev/null | head -n 1 | sed -e 's/.*[^0-9.]\([0-9][0-9]*\.[0-9][0-9.]*\).*/\1/' -e 's/[^0-9.].*//' -e 's/\.*$//'`

# Never let an unparsed string reach a feed URL.  The feed config is
# whitespace-delimited, so a VERSION containing a space silently truncates the
# URL at the first space instead of failing visibly.
case "$VERSION" in
  ''|*[!0-9.]*) VERSION=unknown ;;
esac

# Create the ipkg config and database areas
mkdir -p $APPS/etc/ipkg $APPS/usr/lib/ipkg/cache

# Remove all list database cache files
rm -f $APPS/usr/lib/ipkg/lists/*

# Set up the architecture configuration file
rm -f $APPS/etc/ipkg/arch.conf
cp /etc/ipkg/arch.conf $APPS/etc/ipkg/arch.conf

# Install optware feeds
echo "src/gz optware http://ipkg.preware.net/feeds/optware/all" > $APPS/etc/ipkg/optware.conf
echo "src/gz optware-`/bin/uname -m` http://ipkg.preware.net/feeds/optware/`/bin/uname -m`" >> $APPS/etc/ipkg/optware.conf
sed -i -e 's|armv7l|armv7|g' $APPS/etc/ipkg/optware.conf
sed -i -e 's|armv6l|armv6|g' $APPS/etc/ipkg/optware.conf

# Remove dead webosnation feed
rm -f $APPS/etc/ipkg/precentral.conf

# Install backup webosnation feed
echo "src/gz precentral http://weboslives.eu/feeds/precentral" > $APPS/etc/ipkg/precentral-weboslives.conf

# Install App Museum feed (disabled by default)
echo "src/gz precentral http://weboslives.eu/feeds/wosa" > $APPS/etc/ipkg/wosa-appmuseum.conf.new

# Install PreCentral theme feed
echo "src/gz precentral-themes http://ipkg.preware.net/feeds/precentral-themes" > $APPS/etc/ipkg/precentral-themes.conf.new

# Install PivotCE feeds
echo "src/gz pivotce http://feed.pivotce.com" > $APPS/etc/ipkg/pivotce.conf

# Install prethemer feed
echo "src/gz prethemer http://www.prethemer.com/feeds/preware/themes" > $APPS/etc/ipkg/prethemer.conf.new

# Install clock-themes feed
echo "src/gz clock-themes http://webos-clock-themer.googlecode.com/svn/trunk/WebOS%20Clock%20Theme%20Builder/feed" > $APPS/etc/ipkg/clock-themes.conf.new

# Install webosinternals feeds
echo "src/gz webosinternals http://ipkg.preware.net/feeds/webos-internals/all" > $APPS/etc/ipkg/webos-internals.conf
echo "src/gz webosinternals-`/bin/uname -m` http://ipkg.preware.net/feeds/webos-internals/`/bin/uname -m`" >> $APPS/etc/ipkg/webos-internals.conf
sed -i -e 's|armv7l|armv7|g' $APPS/etc/ipkg/webos-internals.conf
sed -i -e 's|armv6l|armv6|g' $APPS/etc/ipkg/webos-internals.conf

# The patch and kernel feeds are published per OS version.  Nothing has been
# published for 3.1 yet, so an enabled feed there just fails to download every
# time the feeds are updated.  Ship them disabled on 3.1 and later, and also
# when we could not determine the version -- a ".../unknown" feed cannot exist
# either.  3.0.5 and earlier are unaffected.
VERSIONED_FEEDS_DISABLED=0
if [ "$VERSION" = "unknown" ] ; then
  VERSIONED_FEEDS_DISABLED=1
else
  V_MAJ=`echo "$VERSION" | cut -d. -f1`
  V_MIN=`echo "$VERSION" | cut -d. -f2`
  [ -z "$V_MAJ" ] && V_MAJ=0
  [ -z "$V_MIN" ] && V_MIN=0
  if [ "$V_MAJ" -gt 3 ] ; then
    VERSIONED_FEEDS_DISABLED=1
  elif [ "$V_MAJ" -eq 3 ] && [ "$V_MIN" -ge 1 ] ; then
    VERSIONED_FEEDS_DISABLED=1
  fi
fi

if [ "$VERSIONED_FEEDS_DISABLED" -eq 1 ] ; then

  # Write the disabled name directly and drop any enabled one, rather than using
  # the .conf.new mechanism.  These feeds were enabled by default in earlier
  # releases, so on an upgrade a .new would find the existing enabled .conf and
  # keep it enabled -- which is exactly the state we are trying to clear.
  # They can still be switched on from Manage Feeds.

  # Install webos-patches feed (disabled, no content for this OS version)
  rm -f $APPS/etc/ipkg/webos-patches.conf
  echo "src/gz webos-patches http://ipkg.preware.net/feeds/webos-patches/${VERSION:-unknown}" > $APPS/etc/ipkg/webos-patches.conf.disabled

  # Install webos-kernels feed (disabled, no content for this OS version)
  rm -f $APPS/etc/ipkg/webos-kernels.conf
  echo "src/gz webos-kernels http://ipkg.preware.net/feeds/webos-kernels/${VERSION:-unknown}" > $APPS/etc/ipkg/webos-kernels.conf.disabled

else

  # Install webos-patches feed
  echo "src/gz webos-patches http://ipkg.preware.net/feeds/webos-patches/${VERSION:-unknown}" > $APPS/etc/ipkg/webos-patches.conf

  # Install webos-kernels feed
  echo "src/gz webos-kernels http://ipkg.preware.net/feeds/webos-kernels/${VERSION:-unknown}" > $APPS/etc/ipkg/webos-kernels.conf

fi

# Install woce feed
echo "src/gz woce http://ipkg.preware.net/feeds/woce" > $APPS/etc/ipkg/woce.conf

# Install modernize feed (webOS Archive modernization stack: TLS 1.2/1.3, root certs, QupZilla, webOS CE)
echo "src/gz modernize http://stacks.webosarchive.org/feeds/modernize/ipkgs" > $APPS/etc/ipkg/modernize.conf

# Install the alpha testing feeds (disabled by default)

if [ -f /var/preferences/org.webosinternals.preware/enable-alpha-feeds ] ; then

  # Install alpha optware feeds
  echo "src/gz alpha-optware http://ipkg.preware.net/alpha/optware/all" > $APPS/etc/ipkg/alpha-optware.conf.new
  echo "src/gz alpha-optware-`/bin/uname -m` http://ipkg.preware.net/alpha/optware/`/bin/uname -m`" >> $APPS/etc/ipkg/alpha-optware.conf.new
  sed -i -e 's|armv7l|armv7|g' $APPS/etc/ipkg/alpha-optware.conf.new
  sed -i -e 's|armv6l|armv6|g' $APPS/etc/ipkg/alpha-optware.conf.new

  # Install alpha apps feeds
  echo "src/gz alpha-apps http://ipkg.preware.net/alpha/apps/all" > $APPS/etc/ipkg/alpha-apps.conf.new
  echo "src/gz alpha-apps-`/bin/uname -m` http://ipkg.preware.net/alpha/apps/`/bin/uname -m`" >> $APPS/etc/ipkg/alpha-apps.conf.new
  sed -i -e 's|armv7l|armv7|g' $APPS/etc/ipkg/alpha-apps.conf.new
  sed -i -e 's|armv6l|armv6|g' $APPS/etc/ipkg/alpha-apps.conf.new

  # Install alpha patches feed
  echo "src/gz alpha-patches http://ipkg.preware.net/alpha/patches/${VERSION:-unknown}" > $APPS/etc/ipkg/alpha-patches.conf.new

  # Install alpha kernels feed
  echo "src/gz alpha-kernels http://ipkg.preware.net/alpha/kernels/${VERSION:-unknown}" > $APPS/etc/ipkg/alpha-kernels.conf.new

  # Install alpha woce feed
  echo "src/gz alpha-woce http://ipkg.preware.net/alpha/woce" > $APPS/etc/ipkg/alpha-woce.conf.new

  # Remove the obsolete testing feeds
  rm -f $APPS/etc/ipkg/webos-testing*.conf*
  rm -f $APPS/etc/ipkg/optware-testing*.conf*
  rm -f $APPS/etc/ipkg/webos-*-testing*.conf*

fi

# Install the beta testing feeds (disabled by default)

if [ -f /var/preferences/org.webosinternals.preware/enable-beta-feeds ] ; then

  # Install beta optware feeds
  echo "src/gz beta-optware http://ipkg.preware.net/beta/optware/all" > $APPS/etc/ipkg/beta-optware.conf.new
  echo "src/gz beta-optware-`/bin/uname -m` http://ipkg.preware.net/beta/optware/`/bin/uname -m`" >> $APPS/etc/ipkg/beta-optware.conf.new
  sed -i -e 's|armv7l|armv7|g' $APPS/etc/ipkg/beta-optware.conf.new
  sed -i -e 's|armv6l|armv6|g' $APPS/etc/ipkg/beta-optware.conf.new

  # Install beta apps feeds
  echo "src/gz beta-apps http://ipkg.preware.net/beta/apps/all" > $APPS/etc/ipkg/beta-apps.conf.new
  echo "src/gz beta-apps-`/bin/uname -m` http://ipkg.preware.net/beta/apps/`/bin/uname -m`" >> $APPS/etc/ipkg/beta-apps.conf.new
  sed -i -e 's|armv7l|armv7|g' $APPS/etc/ipkg/beta-apps.conf.new
  sed -i -e 's|armv6l|armv6|g' $APPS/etc/ipkg/beta-apps.conf.new

  # Install beta patches feed
  echo "src/gz beta-patches http://ipkg.preware.net/beta/patches/${VERSION:-unknown}" > $APPS/etc/ipkg/beta-patches.conf.new

  # Install beta kernels feed
  echo "src/gz beta-kernels http://ipkg.preware.net/beta/kernels/${VERSION:-unknown}" > $APPS/etc/ipkg/beta-kernels.conf.new

  # Install beta woce feed
  echo "src/gz beta-woce http://ipkg.preware.net/beta/woce" > $APPS/etc/ipkg/beta-woce.conf.new

  # Remove the old testing feeds
  rm -f $APPS/etc/ipkg/webos-testing*.conf*
  rm -f $APPS/etc/ipkg/optware-testing*.conf*
  rm -f $APPS/etc/ipkg/webos-*-testing*.conf*

fi

# Retain disabled status of existing feeds
if [ "`ls $APPS/etc/ipkg/*.disabled`" ] ; then
  for f in $APPS/etc/ipkg/*.disabled ; do
    if [ -f $APPS/etc/ipkg/`basename $f .disabled` ] ; then
      rm -f $f
      mv $APPS/etc/ipkg/`basename $f .disabled` $f
    fi
  done
fi

# Assert disabled status of new feeds
if [ "`ls $APPS/etc/ipkg/*.new`" ] ; then
  for f in $APPS/etc/ipkg/*.new ; do
    if [ -f $APPS/etc/ipkg/`basename $f .new` ] ; then
      rm -f $APPS/etc/ipkg/`basename $f .new`
      mv $f $APPS/etc/ipkg/`basename $f .new`
    else
      rm -f $APPS/etc/ipkg/`basename $f .new`.disabled
      mv $f $APPS/etc/ipkg/`basename $f .new`.disabled
    fi
  done
fi


if ! grep -q "^Package: org.webosinternals.govnah$" $APPS/usr/lib/ipkg/status 2>/dev/null ; then
   mkdir -p $APPS/usr/lib/ipkg
   {
      echo ""
      echo "Package: org.webosinternals.govnah"
      echo "Version: 1.3.9"
      echo "Depends: "
      echo "Status: install ok installed"
      echo "Architecture: arm"
      echo "Description: Govnah"
      echo "Installed-Time: $(date +%s)"
      echo ""
   } >> $APPS/usr/lib/ipkg/status
fi
if ! grep -q "^Package: com.palm.synergy.generic$" $APPS/usr/lib/ipkg/status 2>/dev/null ; then
   mkdir -p $APPS/usr/lib/ipkg
   {
      echo ""
      echo "Package: com.palm.synergy.generic"
      echo "Version: 0.9.3.1"
      echo "Depends: "
      echo "Status: install ok installed"
      echo "Architecture: all"
      echo "Description: Synergy Revival shared runtime"
      echo "Installed-Time: $(date +%s)"
      echo ""
   } >> $APPS/usr/lib/ipkg/status
fi
if ! grep -q "^Package: com.palm.app.backup$" $APPS/usr/lib/ipkg/status 2>/dev/null ; then
   mkdir -p $APPS/usr/lib/ipkg
   {
      echo ""
      echo "Package: com.palm.app.backup"
      echo "Version: 3.1.1"
      echo "Depends: "
      echo "Status: install ok installed"
      echo "Architecture: all"
      echo "Description: Backup and Restore (woce-backup)"
      echo "Installed-Time: $(date +%s)"
      echo ""
   } >> $APPS/usr/lib/ipkg/status
fi
if ! grep -q "^Package: com.palm.app.videos$" $APPS/usr/lib/ipkg/status 2>/dev/null ; then
   mkdir -p $APPS/usr/lib/ipkg
   {
      echo ""
      echo "Package: com.palm.app.videos"
      echo "Version: 3.2.0"
      echo "Depends: "
      echo "Status: install ok installed"
      echo "Architecture: all"
      echo "Description: Videos (webOS CE player)"
      echo "Installed-Time: $(date +%s)"
      echo ""
   } >> $APPS/usr/lib/ipkg/status
fi
if ! grep -q "^Package: com.palm.app.calculator$" $APPS/usr/lib/ipkg/status 2>/dev/null ; then
   mkdir -p $APPS/usr/lib/ipkg
   {
      echo ""
      echo "Package: com.palm.app.calculator"
      echo "Version: 3.2.0"
      echo "Depends: "
      echo "Status: install ok installed"
      echo "Architecture: all"
      echo "Description: Calculator (webOS CE)"
      echo "Installed-Time: $(date +%s)"
      echo ""
   } >> $APPS/usr/lib/ipkg/status
fi
if ! grep -q "^Package: org.webosinternals.browser-tls13$" $APPS/usr/lib/ipkg/status 2>/dev/null ; then
   mkdir -p $APPS/usr/lib/ipkg
   {
      echo ""
      echo "Package: org.webosinternals.browser-tls13"
      echo "Version: 1.1.2"
      echo "Depends: "
      echo "Status: install ok installed"
      echo "Architecture: armv7"
      echo "Description: TLS 1.3 for the browser (Pre-loaded)"
      echo "Installed-Time: $(date +%s)"
      echo ""
   } >> $APPS/usr/lib/ipkg/status
fi
if ! grep -q "^Package: org.webosinternals.downloadmgr-tls13$" $APPS/usr/lib/ipkg/status 2>/dev/null ; then
   mkdir -p $APPS/usr/lib/ipkg
   {
      echo ""
      echo "Package: org.webosinternals.downloadmgr-tls13"
      echo "Version: 1.1.0"
      echo "Depends: "
      echo "Status: install ok installed"
      echo "Architecture: armv7"
      echo "Description: TLS 1.3 for the download manager (Pre-loaded)"
      echo "Installed-Time: $(date +%s)"
      echo ""
   } >> $APPS/usr/lib/ipkg/status
fi
if ! grep -q "^Package: org.webosinternals.luna-tls13$" $APPS/usr/lib/ipkg/status 2>/dev/null ; then
   mkdir -p $APPS/usr/lib/ipkg
   {
      echo ""
      echo "Package: org.webosinternals.luna-tls13"
      echo "Version: 1.1.4"
      echo "Depends: "
      echo "Status: install ok installed"
      echo "Architecture: armv7"
      echo "Description: TLS 1.3 for LunaSysMgr (Pre-loaded)"
      echo "Installed-Time: $(date +%s)"
      echo ""
   } >> $APPS/usr/lib/ipkg/status
fi
if ! grep -q "^Package: org.webosinternals.mail-tls13$" $APPS/usr/lib/ipkg/status 2>/dev/null ; then
   mkdir -p $APPS/usr/lib/ipkg
   {
      echo ""
      echo "Package: org.webosinternals.mail-tls13"
      echo "Version: 1.3.2"
      echo "Depends: "
      echo "Status: install ok installed"
      echo "Architecture: armv7"
      echo "Description: TLS 1.3 for mail (Pre-loaded)"
      echo "Installed-Time: $(date +%s)"
      echo ""
   } >> $APPS/usr/lib/ipkg/status
fi
if ! grep -q "^Package: com.palm.rootcertsupdate$" $APPS/usr/lib/ipkg/status 2>/dev/null ; then
   mkdir -p $APPS/usr/lib/ipkg
   {
      echo ""
      echo "Package: com.palm.rootcertsupdate"
      echo "Version: 1.0-5"
      echo "Depends: "
      echo "Status: install ok installed"
      echo "Architecture: all"
      echo "Description: Updated root certificates (Pre-loaded)"
      echo "Installed-Time: $(date +%s)"
      echo ""
   } >> $APPS/usr/lib/ipkg/status
fi
if ! grep -q "^Package: org.webosarchive.media-tls13$" $APPS/usr/lib/ipkg/status 2>/dev/null ; then
   mkdir -p $APPS/usr/lib/ipkg
   {
      echo ""
      echo "Package: org.webosarchive.media-tls13"
      echo "Version: 1.0.0"
      echo "Depends: "
      echo "Status: install ok installed"
      echo "Architecture: armv7"
      echo "Description: Media TLS 1.3 (Pre-loaded)"
      echo "Installed-Time: $(date +%s)"
      echo ""
   } >> $APPS/usr/lib/ipkg/status
fi
if ! grep -q "^Package: org.webosinternals.curl-tls13$" $APPS/usr/lib/ipkg/status 2>/dev/null ; then
   mkdir -p $APPS/usr/lib/ipkg
   {
      echo ""
      echo "Package: org.webosinternals.curl-tls13"
      echo "Version: 1.0.1"
      echo "Depends: "
      echo "Status: install ok installed"
      echo "Architecture: armv7"
      echo "Description: TLS 1.3 curl (Pre-loaded)"
      echo "Installed-Time: $(date +%s)"
      echo ""
   } >> $APPS/usr/lib/ipkg/status
fi
if ! grep -q "^Package: org.webosinternals.ntpdate-sync$" $APPS/usr/lib/ipkg/status 2>/dev/null ; then
   mkdir -p $APPS/usr/lib/ipkg
   {
      echo ""
      echo "Package: org.webosinternals.ntpdate-sync"
      echo "Version: 2.0.1"
      echo "Depends: "
      echo "Status: install ok installed"
      echo "Architecture: armv7"
      echo "Description: Time sync (Pre-loaded)"
      echo "Installed-Time: $(date +%s)"
      echo ""
   } >> $APPS/usr/lib/ipkg/status
fi
if ! grep -q "^Package: org.webosinternals.patches.notifications-advanced-reset-options$" $APPS/usr/lib/ipkg/status 2>/dev/null ; then
   mkdir -p $APPS/usr/lib/ipkg
   {
      echo ""
      echo "Package: org.webosinternals.patches.notifications-advanced-reset-options"
      echo "Version: 3.0.5-9"
      echo "Depends: "
      echo "Status: install ok installed"
      echo "Architecture: all"
      echo "Description: Advanced reset options (Pre-loaded)"
      echo "Installed-Time: $(date +%s)"
      echo ""
   } >> $APPS/usr/lib/ipkg/status
fi

_seeded=0
for _p in org.webosinternals.govnah com.palm.synergy.generic com.palm.app.backup com.palm.app.videos com.palm.app.calculator org.webosinternals.browser-tls13 org.webosinternals.downloadmgr-tls13 org.webosinternals.luna-tls13 org.webosinternals.mail-tls13 com.palm.rootcertsupdate org.webosarchive.media-tls13 org.webosinternals.curl-tls13 org.webosinternals.ntpdate-sync org.webosinternals.patches.notifications-advanced-reset-options ; do
   grep -q "^Package: $_p$" $APPS/usr/lib/ipkg/status 2>/dev/null && _seeded=$((_seeded+1))
done
echo "CE status stanzas present: $_seeded of 14"

exit 0
